-- name: CreateBook :one
-- The id is generated by the API so that the whole shape-only tree can be
-- built (and stored on the revision) before any node row is inserted.
INSERT INTO books (id, revision_id, label, description, icons, active_index)
VALUES ($1, $2, $3, $4, $5, $6)
RETURNING *;

-- name: ListBooksByRevision :many
SELECT * FROM books WHERE revision_id = $1;
